KIND_IDS = tuple(R.KINDS)
N_SIMILAR = 10
CAP = 5.0                     # any single 12-month return capped at +500% in averages


def plus(d, n):
    return (date.fromisoformat(d) + timedelta(days=n)).isoformat()


# ------------------------------------------------------------------ backend requirements
def leverage(rec, thr):
    """(ok, value, note) - net debt / EBITDA as the screens test it: net cash passes; net debt with no EBITDA fails;
    EBIT stands in when depreciation isn't tagged (stricter)."""
    nd, ebitda, ebit = rec.get("nd"), rec.get("ebitda"), rec.get("ebit")
    if nd is None:
        return False, None, "no balance sheet"
    if not rec.get("debtok") and nd > 0:
        return False, None, "no standard debt tag"
    if nd <= 0:
        return True, None, "net cash"
    if ebitda is None and ebit is not None and ebit > 0:
        return nd / ebit <= thr, nd / ebit, "net debt / EBIT"
    if ebitda is None:
        return False, None, "EBITDA unavailable"
    if ebitda <= 0:
        return False, None, "net debt with no EBITDA"
    return nd / ebitda <= thr, nd / ebitda, ""


def backend(kind, rec):
    """[] when the company is covered by this triage on this scan day, else the reasons it isn't."""
    k = R.KINDS[kind]
    b = k["backend"]
    why = []
    if k["universe"] not in (rec.get("u") or []):
        why.append("industry outside this triage")
    if (rec.get("yrs") or 0) < b["min_years"]:
        why.append(f"fewer than {b['min_years']} years of SEC data")
    if rec.get("ylf") is None or rec["ylf"] > 1.6:
        why.append("latest annual report older than 1.6 years")
    mc = rec.get("mc")
    if mc is None:
        why.append("market cap not verified")
    else:
        if mc < b["min_mcap"]:
            why.append("market cap below the minimum")
        if b["max_mcap"] and mc > b["max_mcap"]:
            why.append("market cap above the maximum")
    if (rec.get("adv") or 0) < b["min_adv"]:
        why.append("trading volume below the minimum")
    if b["min_revenue"] and (rec.get("revfy") or 0) < b["min_revenue"]:
        why.append("revenue below the minimum")
    if not leverage(rec, b["max_lev"])[0]:
        why.append("leverage above the cap or not verifiable")
    return why


# ------------------------------------------------------------------ valuation yields
def yld(kind, rec):
    ev = rec.get("ev")
    if not ev or ev <= 0:
        return None
    if kind == "emerging":
        base = rec.get("ebit") if (rec.get("das") or 0) >= 0.5 else rec.get("ebitda")
        if base is None:
            base = rec.get("ebit")
    else:
        base = rec.get("ebit")
    return None if base is None else base / ev


def pctl(vals, v):
    """Share of vals below v (ties count half)."""
    if not vals:
        return None
    lo = sum(1 for x in vals if x < v)
    eq = sum(1 for x in vals if x == v)
    return (lo + 0.5 * eq) / len(vals)


def peer_groups(comp, kind):
    """{sic prefix: [yields]} for every 4-, 3- and 2-digit industry code (companies of $100M+ with a yield)."""
    g = defaultdict(list)
    for c, r in comp.items():
        if (r.get("mc") or 0) < R.PEER_MIN_MCAP:
            continue
        y = yld(kind, r)
        s = r.get("sic") or ""
        if y is None or len(s) < 2:
            continue
        for n in (4, 3, 2):
            g[s[:n]].append((c, y))
    return g


def peer_pctl(groups, c, rec, y):
    s = rec.get("sic") or ""
    for n in (4, 3, 2):
        mem = [v for cc, v in groups.get(s[:n], []) if cc != c]
        if len(mem) >= R.PEER_MIN:
            return pctl(mem, y), n, len(mem)
    return None, None, 0


# ------------------------------------------------------------------ similar stocks
def _ranks(vals):
    idx = sorted(range(len(vals)), key=lambda k: vals[k])
    r = [0.0] * len(vals)
    for pos, k in enumerate(idx):
        r[k] = pos / max(1, len(vals) - 1)
    return r


def _sub_ranks(vals):
    have = [i for i, v in enumerate(vals) if v is not None]
    out = [None] * len(vals)
    for i, rk in zip(have, _ranks([vals[i] for i in have])):
        out[i] = rk
    return out


def similar_pool(comp):
    """[(cik, rank mc, rank r12, rank ey, mc, r12, ey)] of US companies of $100M+ with a price (12-month change and
    earnings yield may be missing: the first year of the grid has no 12-month change)."""
    rows = [(c, r["mc"], r.get("r12"), (r["ebit"] / r["ev"]) if (r.get("ebit") is not None and r.get("ev")) else None)
            for c, r in comp.items() if (r.get("mc") or 0) >= R.PEER_MIN_MCAP and r.get("px")]
    if len(rows) <= N_SIMILAR:
        return []
    rm, rr, re_ = _ranks([x[1] for x in rows]), _sub_ranks([x[2] for x in rows]), _sub_ranks([x[3] for x in rows])
    return [(rows[i][0], rm[i], rr[i], re_[i], rows[i][1], rows[i][2], rows[i][3]) for i in range(len(rows))]


def nearest(pool, c, rec, busy):
    """The 10 closest companies on market cap, 12-month price change and earnings yield (percentile ranks that day;
    a measure the company lacks is skipped, one a candidate lacks counts as the largest gap), leaving out the company
    itself and companies with an event of the same triage in the last 6 months."""
    if not pool or rec.get("mc") is None:
        return []
    pm = sum(1 for x in pool if x[4] < rec["mc"]) / len(pool)
    r12s = [x[5] for x in pool if x[5] is not None]
    pr = (sum(1 for v in r12s if v < rec["r12"]) / len(r12s)) if (rec.get("r12") is not None and r12s) else None
    ey = (rec["ebit"] / rec["ev"]) if (rec.get("ebit") is not None and rec.get("ev")) else None
    eys = [x[6] for x in pool if x[6] is not None]
    pe = (sum(1 for v in eys if v < ey) / len(eys)) if (ey is not None and eys) else None
    scored = []
    for x in pool:
        if x[0] == c or x[0] in busy:
            continue
        dist = abs(x[1] - pm)
        for mine, theirs in ((pr, x[2]), (pe, x[3])):
            if mine is not None:
                dist += abs(theirs - mine) if theirs is not None else 1.0
        scored.append((dist, x[0]))
    scored.sort()
    return [k for _, k in scored[:N_SIMILAR]]


# ------------------------------------------------------------------ detection (one pass over the panel)
def detect(months, load=PN.load, log=print):
    """{kind: [event, ...]} - events need the previous scan's trigger state, so the first scan only primes it."""
    out = {k: [] for k in KIND_IDS}
    hist = {k: defaultdict(lambda: deque(maxlen=R.OWN_PAST)) for k in KIND_IDS if k != "hidden"}
    state = {k: {} for k in KIND_IDS}               # cik -> trigger held at the previous scan (True / False)
    last = {k: {} for k in KIND_IDS}                # cik -> scan index of its latest event
    ebit_back = deque(maxlen=R.PER_YEAR + 1)     # {cik: TTM EBIT} of the last year of scans (profit trend)
    for i, ym in enumerate(months):
        p = load(ym) or {}
        comp = p.get("companies") or {}
        if not comp:
            ebit_back.append({})
            continue
        pool = similar_pool(comp)
        year_ago = ebit_back[0] if len(ebit_back) == R.PER_YEAR + 1 else {}
        new_state = {k: {} for k in KIND_IDS}
        for kind in KIND_IDS:
            groups = peer_groups(comp, kind) if kind != "hidden" else None
            busy = {c for c, j in last[kind].items() if i - j < R.COOLDOWN}
            evs = []
            for c, rec in comp.items():
                if kind == "hidden":
                    trig = None if rec.get("dd") is None else rec["dd"] <= R.HIDDEN_FALL
                    info = {"dd": rec.get("dd")}
                else:
                    y = yld(kind, rec)
                    past = list(hist[kind][c]) if c in hist[kind] else []
                    p_own = pctl(past, y) if (y is not None and len(past) >= R.OWN_PAST_MIN) else None
                    p_peer, lvl, npeer = peer_pctl(groups, c, rec, y) if y is not None else (None, None, 0)
                    trig = None if (p_own is None and p_peer is None) else \
                        ((p_own or 0) >= R.CHEAP_PCTL or (p_peer or 0) >= R.CHEAP_PCTL)
                    info = {"y": y, "p_own": p_own, "n_own": len(past), "p_peer": p_peer, "peer_lvl": lvl,
                            "n_peer": npeer, "y_med": st.median(past) if past else None}
                    if y is not None:
                        hist[kind][c].append(y)
                new_state[kind][c] = trig
                if not trig or state[kind].get(c) is not False or c in busy:
                    continue
                if backend(kind, rec):
                    continue
                evs.append((c, rec, info))
            for c, rec, info in evs:
                last[kind][c] = i
            busy = {c for c, j in last[kind].items() if i - j < R.COOLDOWN}
            for c, rec, info in evs:
                sim = nearest(pool, c, rec, busy)
                out[kind].append({"id": f"{c}_{ym}", "cik": c, "ym": ym, "i": i, "d": p["d"], "e": p["e"],
                                  "rec": rec, "info": info, "ebit_1y": year_ago.get(c), "sim": sim,
                                  "sim_sym": {k: comp[k].get("sym") for k in sim}})
        state = new_state
        ebit_back.append({c: r.get("ebit") for c, r in comp.items()})
        if (i + 1) % R.PER_YEAR == 0 or i == len(months) - 1:
            log(f"  events through {ym}: " + ", ".join(f"{k} {len(v)}" for k, v in out.items()))
    return out


# ------------------------------------------------------------------ returns
class Returns:
    """Scan-to-scan returns from cache/tri/returns, plus the open period marked to the latest close."""

    def __init__(self, months, grid_e, mark=None, opens=None, splits=None, divs=None):
        self.months = months
        self.e = grid_e                                     # ym -> entry day
        self.r = {ym: read_json(os.path.join(P.RETURNS, f"{ym}.json.gz")) for ym in months}
        self.idx = read_json(os.path.join(P.RETURNS, "index.json.gz")) or {}
        self.mark, self.opens = mark or {}, opens or {}
        self.splits, self.divs = splits or {}, divs or {}

    def _partial(self, sym, ym):
        """Open of the month's entry day to the latest close (None if either is missing)."""
        cl = (self.mark.get("closes") or {}).get(sym)
        op = self.opens.get(sym)
        if not cl or not op or not self.mark.get("day") or self.mark["day"] < self.e.get(ym, "9"):
            return None
        return holding_return(op, cl, self.splits.get(sym) or [], self.divs.get(sym) or [], self.e[ym], self.mark["day"])

    def path(self, key, sym, i0, n=R.PER_YEAR, index=False):
        """([cumulative return after 0..k months], complete?, last day, stopped?) from the entry of month i0."""
        vals, cum, exited, stopped = [0.0], 1.0, False, None
        last_day = self.e.get(self.months[i0]) if i0 < len(self.months) else None
        for k in range(n):
            i = i0 + k
            if i >= len(self.months):
                return vals, False, last_day, stopped
            ym = self.months[i]
            rets = (self.idx.get(ym) if index else self.r.get(ym))
            if rets is None:
                part = 0.0 if exited else self._partial(sym, ym)
                if part is not None and self.mark.get("day"):
                    vals.append(cum * (1 + part) - 1)
                    last_day = self.mark["day"]
                return vals, False, last_day, stopped
            if exited:
                r = 0.0
            else:
                v = rets.get(str(key)) if not index else rets.get(key)
                if index:
                    r = v if v is not None else 0.0
                elif v is None:
                    if k == 0:
                        return None, False, None, None           # no entry price
                    r, exited, stopped = 0.0, True, ym
                else:
                    r = v[0]
                    if v[1] != "ok":
                        exited, stopped = True, ym
            cum *= 1 + r
            vals.append(cum - 1)
            nxt = self.months[i + 1] if i + 1 < len(self.months) else None
            last_day = self.e.get(nxt) if nxt else last_day
        return vals, True, last_day, stopped

    def series(self, key, sym, i0, ym_set):
        """{entry day of the period: return to the next entry day} over an event's 12 months (calendar-time
        portfolios group these by the calendar month the period starts in)."""
        out = {}
        for k in range(R.PER_YEAR):
            i = i0 + k
            if i >= len(self.months):
                break
            ym = self.months[i]
            rets = self.r.get(ym)
            if rets is None:
                break
            v = rets.get(str(key))
            out[self.e[ym]] = v[0] if v else 0.0
            if v is None or v[1] != "ok":
                break
        return out


# ------------------------------------------------------------------ 13F owners
def quarter_before(d):
    y = int(d[:4])
    ends = sorted(f"{yy}-{mm:02d}-{dd}" for yy in (y, y - 1) for mm, dd in ((12, 31), (9, 30), (6, 30), (3, 31)))
    return [x for x in ends if plus(x, 45) <= d][-1]


def quarter_of(d):
    y, m = int(d[:4]), int(d[5:7])
    q = (m - 1) // 3
    return f"{y}-{3 * q + 3:02d}-{[31, 30, 30, 31][q]}"


class Owners:
    def __init__(self, rows, through, first_day=None):
        self.by_cik = defaultdict(list)
        self.names = {}
        for r in rows:
            fc, nm, per, fd, cik, w = r
            self.by_cik[str(cik)].append((fc, nm, per, fd, w))
            self.names[fc] = nm
        self.through, self.first = through, first_day

    def funds(self, cik, d):
        """None when the 13F data doesn't cover the date yet, else {'list', 'later', 'before', 'after', 'pending'}."""
        qb, qa = quarter_before(d), quarter_of(d)
        if self.through is None or self.through < plus(qb, 45) or (self.first and self.first > plus(qb, 1)):
            return None
        best, later = {}, {}
        for fc, nm, per, fd, w in self.by_cik.get(str(cik), []):
            if per == qb and fd <= d and (fc not in best or w > best[fc][2]):
                best[fc] = (fc, nm, w, per)
        for fc, nm, per, fd, w in sorted(self.by_cik.get(str(cik), []), key=lambda t: t[3]):
            if per == qa and d < fd <= plus(qa, 45) and fc not in best and fc not in later:
                later[fc] = (fc, nm, w, fd)
        return {"before": qb, "after": qa, "pending": self.through < plus(qa, 45),
                "list": sorted(best.values(), key=lambda t: -t[2]), "later": list(later.values())}


def top_performers(events_all):
    """as_of(day) -> {filer_cik: (rank, score, hits, plays, rate, conc)} from events whose 12 months had ended by
    that day (all three triages). Half quality (conviction-weighted, shrunk hit rate x concentration), half number of
    hits, each a percentile rank among filers with plays in 5+ companies. Hit = beat its similar stocks by 10+ points."""
    done = sorted((x for x in events_all if x.get("y") is not None and x.get("fund") and x.get("end")),
                  key=lambda x: x["end"])
    cache = {}

    def pct_rank(vals):
        order = sorted(vals)
        return [(sum(1 for o in order if o < v) + 0.5 * sum(1 for o in order if o == v)) / len(order) for v in vals]

    def as_of(d):
        if d in cache:
            return cache[d]
        plays = defaultdict(list)
        for x in done:
            if x["end"] > d:
                break
            hit = x["y"] >= R.TOP_HIT
            for fc, _, w, _ in x["fund"]["list"] + x["fund"]["later"]:
                plays[fc].append((w, hit, x["cik"]))
        allp = [p for v in plays.values() for p in v]
        elig = {fc: v for fc, v in plays.items() if len({c for _, _, c in v}) >= R.TOP_MIN_COMPANIES}
        if not elig:
            cache[d] = {}
            return cache[d]
        cap = R.TOP_WEIGHT_CAP
        base = sum(min(w, cap) * h for w, h, _ in allp) / sum(min(w, cap) for w, _, _ in allp)
        wbar = sum(min(w, cap) for w, _, _ in allp) / len(allp)
        med = lambda v: sorted(v)[len(v) // 2]  # noqa: E731
        med_all = med([med([w for w, _, _ in v]) for v in elig.values()])
        stats = []
        for fc, v in elig.items():
            sw = sum(min(w, cap) for w, _, _ in v)
            sh = sum(min(w, cap) * h for w, h, _ in v)
            rate = (sh + R.TOP_PRIOR_PLAYS * wbar * base) / (sw + R.TOP_PRIOR_PLAYS * wbar)
            conc = min(med([w for w, _, _ in v]) / med_all, R.TOP_CONC_CAP) if med_all else 1.0
            stats.append((fc, rate, conc, sum(h for _, h, _ in v), len(v)))
        q = pct_rank([r * c for _, r, c, _, _ in stats])
        n = pct_rank([h for _, _, _, h, _ in stats])
        scored = sorted(((t[0], (qq + nn) / 2, t[1], t[2], t[3], t[4]) for t, qq, nn in zip(stats, q, n)),
                        key=lambda t: (-t[1], t[0]))[:R.TOP_N]
        cache[d] = {fc: (i + 1, sc, hits, k, rate, conc) for i, (fc, sc, rate, conc, hits, k) in enumerate(scored)}
        return cache[d]
    return as_of


# ------------------------------------------------------------------ insiders
def insider_view(trades, d, mcap):
    """Net open-market buying minus discretionary selling filed in the 180 days up to d."""
    lo = plus(d, -R.INSIDER_DAYS)
    win = [t for t in trades if lo < t[1] <= d]
    buy = sum(t[3] for t in win if t[2] == "P")
    sell = sum(t[3] for t in win if t[2] == "S")
    plan = sum(t[3] for t in win if t[2] in ("Splan", "Sex"))
    net = buy - sell
    mat = max(R.INSIDER_MIN_USD, R.INSIDER_MIN_MCAP_SHARE * (mcap or 0))
    big = max((t for t in win if t[2] in ("P", "S")), key=lambda t: t[3], default=None)
    return {"buy": buy, "sell": sell, "plan": plan, "net": net, "material": mat, "n": len(win), "largest": big,
            "colour": "g" if net >= mat else "r" if net <= -mat else "n"}


# -------------------------------------------------------------------------------- from triage/score.py
from bisect import bisect_left



NA = ["n", "N/A", "", "N/A"]


def money(v):
    a = abs(v or 0)
    s = f"${a / 1e9:.1f}B" if a >= 1e9 else f"${a / 1e6:.0f}M" if a >= 1e7 else f"${a / 1e6:.1f}M" if a >= 1e6 \
        else f"${a / 1e3:.0f}K" if a >= 1e3 else f"${a:.0f}"
    return s


def pct(v, d=0, sign=False):
    if v is None:
        return "N/A"
    s = f"{abs(v) * 100:.{d}f}%"
    return (("+" if v > 0 else "−" if v < 0 else "") if sign else ("−" if v < 0 else "")) + s


def pts(v):
    return f"{'+' if v >= 0 else '−'}{abs(v) * 100:.1f} pts"


def cell(kind, key, v, text, note, buckets):
    """Colour by the band, bucket by the colour (buckets: (green, neutral, red) labels)."""
    if v is None:
        return list(NA)
    c = R.band(kind, key, v)
    return [c, text, note, buckets[{"g": 0, "n": 1, "r": 2}[c]]]


# ------------------------------------------------------------------ thesis cells
def c_trend(kind, ev):
    now, then = ev["rec"].get("ebit"), ev.get("ebit_1y")
    if now is None or then is None:
        return list(NA)
    note = f"Operating income, last 12 months: {money(now)} vs {money(then)} a year earlier (as filed by each scan)"
    if then > 0:
        g = now / then - 1
        return cell(kind, "trend", g, pct(g, 0, True), note, ("Up", "Down a little", "Down a lot"))
    if now > 0:
        return ["g", "Back to profit", note, "Up"]
    return ["r", "Loss both years", note, "Down a lot"]


def c_simple(kind, key, v, fmt, note, buckets):
    return cell(kind, key, v, fmt(v) if v is not None else "N/A", note, buckets)


def thesis_cells(kind, ev):
    r, info = ev["rec"], ev["info"]
    out = {}
    if kind == "hidden":
        out["trend"] = c_trend(kind, ev)
        fy = (r["fcf"] / r["mc"]) if (r.get("fcf") is not None and r.get("mc")) else None
        out["fcf"] = c_simple(kind, "fcf", fy, lambda v: pct(v, 1),
                              f"Free cash flow, last 12 months ({money(r.get('fcf'))}) ÷ market cap ({money(r.get('mc'))})",
                              ("6%+", "0–6%", "Negative"))
        ee = (r["ev"] / r["ebit"]) if (r.get("ev") and r.get("ebit") and r["ebit"] > 0) else None
        out["ev_ebit"] = c_simple(kind, "ev_ebit", ee, lambda v: f"{v:.1f}×",
                                  f"EV ({money(r.get('ev'))}: market cap + debt − cash) ÷ operating income, last 12 months",
                                  ("10× or less", "10–15×", "Over 15×"))
        out["roic"] = c_simple(kind, "roic", r.get("roic"), lambda v: pct(v),
                               "Median return on invested capital over up to 10 fiscal years", ("12%+", "8–12%", "Under 8%"))
        out["sales"] = c_simple(kind, "sales", r.get("rc3"), lambda v: pct(v, 0, True) + "/yr",
                                "Revenue growth per year over 3 fiscal years", ("Growing", "Down 0–5%/yr", "Down 5%+/yr"))
        return out
    yname = "EBITDA yield" if kind == "emerging" else "Earnings yield (EBIT / EV)"
    if info.get("p_own") is not None:
        out["own"] = cell(kind, "own", info["p_own"], f"Cheaper than {round(info['p_own'] * 100)}%",
                          f"{yname} {pct(info['y'], 1)} vs its median {pct(info.get('y_med'), 1)} over its last "
                          f"{info['n_own']} scans: cheaper than {round(info['p_own'] * 100)}% of them",
                          ("Cheapest fifth", "Cheaper than its median", "Dearer than its median"))
    else:
        out["own"] = ["n", "N/A", f"Needs {R.OWN_PAST_MIN_MONTHS} months of its own history", "N/A"]
    if info.get("p_peer") is not None:
        out["peers"] = cell(kind, "peers", info["p_peer"], f"Cheaper than {round(info['p_peer'] * 100)}%",
                            f"{yname} {pct(info['y'], 1)}: cheaper than {round(info['p_peer'] * 100)}% of {info['n_peer']} companies of $100M+ with industry "
                            f"code {(r.get('sic') or '')[:info['peer_lvl']]} ({info['peer_lvl']}-digit) that day",
                            ("Cheapest fifth", "Cheaper than median", "Dearer than median"))
    else:
        out["peers"] = ["n", "N/A", f"Fewer than {R.PEER_MIN} industry peers with a yield", "N/A"]
    if kind == "emerging":
        out["growth"] = c_simple(kind, "growth", r.get("rc3"), lambda v: pct(v, 0, True) + "/yr",
                                 "Revenue growth per year over 3 fiscal years", ("15%+/yr", "5–15%/yr", "Under 5%/yr"))
        g, src = (r.get("ytdg"), "year-to-date vs the same months a year earlier") if r.get("ytdg") is not None else \
            (r.get("fyg"), "latest fiscal year (no year-to-date figure)")
        out["recent"] = c_simple(kind, "recent", g, lambda v: pct(v, 0, True), f"Revenue growth, {src}",
                                 ("8%+", "0–8%", "Shrinking"))
        m = r.get("em3") if r.get("em3") is not None else r.get("om3")
        s = r.get("sga3")
        if m is None and s is None:
            out["oplev"] = ["n", "N/A", "No margin or SG&A history", "N/A"]
        else:
            col = "g" if (m is not None and m >= 0) else "n" if (s is not None and s <= 0) else "r"
            txt = f"Margin {pts(m)}" if m is not None else f"SG&A {pts(s)}"
            out["oplev"] = [col, txt, "3-year change in EBITDA margin (operating margin if no EBITDA)"
                            + (f"; SG&A ÷ revenue {pts(s)}" if s is not None else ""),
                            {"g": "Margin up", "n": "Overheads down", "r": "Both worse"}[col]]
        if r.get("gm") is None and not r.get("gprep"):
            out["gm"] = ["n", "N/A", "No cost-of-sales line (service business)", "N/A"]
        else:
            out["gm"] = c_simple(kind, "gm", r.get("gm"), lambda v: pct(v), "Gross margin, last 12 months",
                                 ("35%+", "20–35%", "Under 20%"))
        out["dilution"] = c_simple(kind, "dilution", r.get("sh3"), lambda v: pct(v, 1, True) + "/yr",
                                   "Share count growth per year over 3 years", ("3%/yr or less", "3–8%/yr", "Over 8%/yr"))
    else:
        out["roic"] = c_simple(kind, "roic", r.get("roic"), lambda v: pct(v),
                               "Median return on invested capital over up to 10 fiscal years", ("15%+", "10–15%", "Under 10%"))
        out["persist"] = c_simple(kind, "persist", r.get("roics"), lambda v: pct(v) + " of years",
                                  "Share of fiscal years with return on invested capital of 10%+", ("80%+", "60–80%", "Under 60%"))
        out["growth"] = c_simple(kind, "growth", r.get("rc"), lambda v: pct(v, 0, True) + "/yr",
                                 "Revenue growth per year over up to 10 fiscal years", ("5%+/yr", "0–5%/yr", "Shrinking"))
        out["conversion"] = c_simple(kind, "conversion", r.get("fcfc"), lambda v: f"{v:.2f}×",
                                     "Free cash flow ÷ net income, summed over the fiscal years", ("0.8×+", "0.5–0.8×", "Under 0.5×"))
        out["trend"] = c_trend(kind, ev)
    return out


def hard_avoid(kind, r):
    if kind == "emerging":
        heavy = (r.get("das") or 0) >= 0.5
        a, b = (r.get("ebit"), r.get("fyebit")) if heavy or r.get("ebitda") is None else (r.get("ebitda"), r.get("fyebitda"))
        if (a is not None and a <= 0) or (b is not None and b <= 0):
            return [R.KINDS[kind]["hard"][0][1]]
        return []
    e = r.get("ebit")
    return [R.KINDS[kind]["hard"][0][1]] if (e is not None and e <= 0) else []


# ------------------------------------------------------------------ owners and insiders cells
def c_insider(ev):
    v = ev.get("ins")
    if v is None:
        return list(NA)
    if v["n"] == 0:
        return ["n", "None", "No open-market buys or discretionary sales in Form 4s filed in the 180 days to the "
                "scan", "None"]
    big = v["largest"]
    note = (f"Open-market buys {money(v['buy'])}, discretionary sales {money(v['sell'])}"
            + (f", plan / option-exercise sales {money(v['plan'])} (not counted)" if v["plan"] else "")
            + f"; counts at {money(v['material'])}+ (the larger of $25K and 0.01% of market cap)")
    if big:
        note += f". Largest: {big[4]}{' (' + big[5] + ')' if big[5] else ''} {money(big[3])} on {big[0]}"
    if v["colour"] == "n":
        return ["n", "Small", note, "None"]
    return [v["colour"], f"{'Bought' if v['net'] > 0 else 'Sold'} {money(abs(v['net']))}", note,
            "Bought" if v["net"] > 0 else "Sold"]


def c_funds(ev):
    f = ev.get("fund")
    if f is None:
        return list(NA)
    n = len(f["list"])
    head = ("; ".join(f"{nm} {w * 100:.1f}%" for _, nm, w, _ in f["list"][:8]) + f" (end of {f['before']})") if n \
        else f"No high conviction owner held it at 3%+ of its portfolio at the end of {f['before']}"
    later = "; ".join(f"{nm} {w * 100:.1f}% (filed {d})" for _, nm, w, d in f["later"][:6])
    note = head + (f" · Later, for {f['after']}: {later}" if later else "")
    return ["g" if n >= 2 else "n", "None" if n == 0 else f"{n} fund{'s' if n > 1 else ''}", note,
            "None" if n == 0 else "1 fund" if n == 1 else "2+ funds"]


def c_top(ev):
    if ev.get("fund") is None:
        return list(NA)
    t, tl = ev.get("top") or [], ev.get("top_later") or []
    note = "; ".join([f"{n} (top {rk}: {h} of {k} plays beat similar stocks by 10+ points)" for n, rk, h, k in t] +
                     [f"{n} (top {rk}), 13F filed {d}" for n, rk, h, k, d in tl])
    if t:
        return ["g", "Yes", note, "Yes"]
    if tl:
        return ["n", f"Yes, {tl[0][4]}", note, "Yes"]
    return ["n", "No", note or "No top performer owner among its high conviction owners", "No"]


# ------------------------------------------------------------------ one event
def evaluate(kind, ev, ins_through, months_d, rets, index_sym):
    r = ev["rec"]
    cells = thesis_cells(kind, ev)
    cells["insider"] = c_insider(ev)
    cells["funds"] = c_funds(ev)
    cells["top"] = c_top(ev)
    order = [k for k, _, _ in R.KINDS[kind]["cells"]]
    cells = {k: cells.get(k, list(NA)) for k in order}
    colours = {k: (c[0] if c[1] != "N/A" else None) for k, c in cells.items()}
    hard = hard_avoid(kind, r)
    verdict, why, s = R.call(kind, colours, hard)
    pending = []
    if ev.get("fund") is None:
        pending.append("13F holdings for this date not loaded yet")
    if ev.get("ins") is None:
        pending.append("insider trades for this date not loaded yet")
    call_i, call_date, upgraded = ev["i"], ev["d"], None
    if verdict == "close" and ev.get("top_later"):
        fd = ev["top_later"][0][4]
        j = bisect_left(months_d, fd)                 # first scan on or after the 13F filing
        if j < len(months_d):
            call_i, call_date = j, fd
            verdict, upgraded = "overdone", f"Watch until {fd}: a top performer owner's 13F filed then"
            why = [upgraded]
    if pending:
        verdict, why, call_i, call_date, upgraded = "tbu", pending, ev["i"], ev["d"], None
    out = {"id": ev["id"], "cik": ev["cik"], "name": r.get("nm") or "", "ticker": r.get("tk") or "",
           "date": ev["d"], "ym": ev["ym"], "sic": r.get("sic"), "verdict": verdict, "why": why, "score": s,
           "call_date": call_date, "upgraded": upgraded, "mcap": r.get("mc"), "price": r.get("px"),
           "factors": cells, "insider_net": (ev.get("ins") or {}).get("net"),
           "move": round(r["dd"] * 100, 1) if kind == "hidden" and r.get("dd") is not None else None,
           "p_own": ev["info"].get("p_own"), "p_peer": ev["info"].get("p_peer")}
    # outcome from the call's entry day
    sym = r.get("sym")
    own = rets.path(ev["cik"], sym, call_i)
    if own[0] is None:
        out["no_entry"] = True
        return out, None
    vals, complete, last_day, stopped = own
    out["entry_date"] = rets.e.get(rets.months[call_i]) if call_i < len(rets.months) else None
    out["path"] = monthly(vals)
    out["ret"], out["ret_to"], out["played"] = round(vals[-1] * 100, 1), last_day, complete
    if stopped:
        out["stopped"] = stopped
    sims = []
    for c in ev.get("sim") or []:
        p = rets.path(c, ev.get("sim_sym", {}).get(c), call_i)
        if p[0] is not None and len(p[0]) == len(vals):
            sims.append([min(v, CAP) for v in p[0]])
    if sims:
        cp = [sum(s_[k] for s_ in sims) / len(sims) for k in range(len(vals))]
        out["ctrl_path"] = monthly(cp)
        out["ctrl_ret"] = round(cp[-1] * 100, 1)
    ip = rets.path(index_sym, index_sym, call_i, index=True)
    if ip[0] is not None and len(ip[0]) == len(vals):
        out["idx_path"] = monthly(ip[0])
        out["idx_ret"] = round(ip[0][-1] * 100, 1)
    if complete:
        out["outcome"] = R.outcome(vals[-1])
    learn = None
    if complete and sims and verdict != "tbu":
        learn = {"y": vals[-1] - cp[-1], "abs": vals[-1], "end": last_day}
    return out, learn


def monthly(vals):
    """Cumulative returns per scan -> one point per month after buying (and the latest point of an open event)."""
    step = R.PER_YEAR // 12
    out = vals[::step]
    if (len(vals) - 1) % step:
        out = out + [vals[-1]]
    return [round(v * 100, 2) for v in out]


def write(kind, items):
    P.ensure(P.OUT)
    write_json(f"{P.OUT}/{kind}.json.gz", items)


# -------------------------------------------------------------------------------- from triage/stats.py
import math
import statistics as st
from collections import defaultdict

import numpy as np



CALLS = ("overdone", "close", "justified")
CAP_PCT = 500.0


def mean(v):
    v = [x for x in v if x is not None]
    return sum(v) / len(v) if v else None


def _r1(v):
    return None if v is None else round(v, 1)


def calls_table(items):
    out = {}
    for v in CALLS:
        g = [x for x in items if x.get("verdict") == v and x.get("played") and x.get("ret") is not None]
        if not g:
            continue
        a = [x["ret"] for x in g]
        c = [x["ctrl_ret"] for x in g if x.get("ctrl_ret") is not None]
        ix = [x["idx_ret"] for x in g if x.get("idx_ret") is not None]
        beat = [x["ret"] > x["ctrl_ret"] for x in g if x.get("ctrl_ret") is not None]
        out[v] = {"n": len(g), "median": _r1(st.median(a)), "mean": _r1(mean([min(x, CAP_PCT) for x in a])),
                  "ctrl_mean": _r1(mean(c)), "idx_mean": _r1(mean(ix)),
                  "beat": round(100 * sum(beat) / len(beat)) if beat else None,
                  "up20": round(100 * sum(x >= 20 for x in a) / len(a)), "down50": round(100 * sum(x <= -50 for x in a) / len(a))}
    return out


def avg_path(paths, carry=False):
    out, n = [], max((len(p) for p in paths), default=0)
    for k in range(n):
        v = [p[k] if len(p) > k else (p[-1] if carry and p else None) for p in paths]
        v = [min(x, CAP_PCT) for x in v if x is not None]
        if not v:
            break
        out.append(round(sum(v) / len(v), 2))
    return out


def track(items):
    buys = [x for x in items if x.get("verdict") == "overdone" and x.get("played") and x.get("path")
            and x.get("ctrl_path") and x.get("idx_path") and len(x["path"]) == 13]
    if not buys:
        return None
    return {"n": len(buys), "own": avg_path([x["path"] for x in buys]), "ctrl": avg_path([x["ctrl_path"] for x in buys]),
            "idx": avg_path([x["idx_path"] for x in buys])}


def years(items):
    out = {}
    buys = [x for x in items if x.get("verdict") == "overdone" and x.get("path")]
    for y in sorted({x["call_date"][:4] for x in buys}):
        g = [x for x in buys if x["call_date"][:4] == y]
        pth = {"own": avg_path([x["path"] for x in g], True),
               "ctrl": avg_path([x.get("ctrl_path") or [] for x in g if x.get("ctrl_path")], True),
               "idx": avg_path([x.get("idx_path") or [] for x in g if x.get("idx_path")], True)}
        fin = lambda k: round(10000 * (1 + pth[k][-1] / 100)) if pth[k] else None  # noqa: E731
        out[y] = {"n": len(g), "open": sum(1 for x in g if not x.get("played")), "own": fin("own"), "ctrl": fin("ctrl"),
                  "idx": fin("idx"), "path": pth}
    return out


def evidence(kind, items):
    """{cell: {'g': {...}, 'n': {...}, 'r': {...}}} - excess one-year return over the similar stocks."""
    done = [x for x in items if x.get("played") and x.get("ret") is not None and x.get("ctrl_ret") is not None
            and x.get("verdict") in CALLS]
    out = {}
    for k, label, w in R.KINDS[kind]["cells"]:
        row = {}
        for col in ("g", "n", "r"):
            ex = [x["ret"] - x["ctrl_ret"] for x in done
                  if (x["factors"].get(k) or ["n", "N/A"])[1] != "N/A" and x["factors"][k][0] == col]
            if ex:
                row[col] = {"n": len(ex), "median": _r1(st.median(ex)), "mean": _r1(mean([min(e, CAP_PCT) for e in ex])),
                            "beat": round(100 * sum(e > 0 for e in ex) / len(ex))}
        na = sum(1 for x in done if (x["factors"].get(k) or ["n", "N/A"])[1] == "N/A")
        out[k] = {"label": label, "weight": w, "cols": row, "na": na}
    return out


def portfolios(items, series):
    """{call: {YYYY-MM: monthly return}} - calendar-time portfolios of held events: equal-weighted each scan period
    (rebalanced twice a month), compounded to calendar months for the monthly factor data."""
    acc = {v: defaultdict(list) for v in CALLS}
    for x in items:
        v = x.get("verdict")
        if v not in CALLS:
            continue
        for per, r in (series.get(x["id"]) or {}).items():
            acc[v][per].append(r)
    out = {}
    for v, m in acc.items():
        mon = defaultdict(lambda: 1.0)
        for per, rs in sorted(m.items()):
            mon[per[:7]] *= 1 + sum(rs) / len(rs)
        out[v] = {ym: g - 1 for ym, g in sorted(mon.items())}
    return out


def regress(series, factors, rf=True):
    yms = [ym for ym in sorted(series) if ym in factors and all(factors[ym].get(k) is not None for k in FACTORS)]
    if len(yms) < 12:
        return {"n": len(yms), "alpha": None}
    y = [series[ym] - (factors[ym].get("RF", 0.0) if rf else 0.0) for ym in yms]
    X = np.array([[factors[ym][k] for k in FACTORS] for ym in yms])
    b, t, n = ols_nw(y, X)
    if b is None:
        return {"n": n, "alpha": None}
    yy = np.asarray(y)
    fit = np.column_stack([np.ones(len(yy)), X]) @ b
    ss_res, ss_tot = float(((yy - fit) ** 2).sum()), float(((yy - yy.mean()) ** 2).sum())
    return {"n": n, "first": yms[0], "last": yms[-1], "mean_m": round(float(np.mean(series_list(series, yms))) * 100, 2),
            "alpha_m": round(float(b[0]) * 100, 3), "alpha_y": round(((1 + float(b[0])) ** 12 - 1) * 100, 1),
            "t": round(float(t[0]), 2), "r2": round(1 - ss_res / ss_tot, 2) if ss_tot > 0 else None,
            "betas": {k: [round(float(bb), 2), round(float(tt), 1)] for k, bb, tt in zip(FACTORS, b[1:], t[1:])}}


def series_list(series, yms):
    return [series[ym] for ym in yms]


def regression(items, series, factors):
    if not factors:
        return None
    p = portfolios(items, series)
    out = {v: regress(p[v], factors) for v in CALLS if p[v]}
    ls = {ym: p["overdone"][ym] - p["justified"][ym] for ym in p["overdone"] if ym in p["justified"]}
    if ls:
        out["long_short"] = regress(ls, factors, rf=False)
    out["months_held"] = {v: len(p[v]) for v in CALLS}
    return out


def summary(kind, items, series, factors):
    return {"calls": calls_table(items), "track": track(items), "years": years(items),
            "evidence": evidence(kind, items), "regression": regression(items, series, factors)}


def finite(v):
    return v is not None and not (isinstance(v, float) and (math.isnan(v) or math.isinf(v)))


# -------------------------------------------------------------------------------- from triage/build.py (_event_learning)
def _event_learning(ev, rets):
    """Outcome measured from the event's own entry (whatever the call), for ranking 13F filers."""
    p = rets.path(ev["cik"], ev["rec"].get("sym"), ev["i"])
    if p[0] is None or not p[1]:
        return None
    sims = []
    for c in ev.get("sim") or []:
        q = rets.path(c, (ev.get("sim_sym") or {}).get(c), ev["i"])
        if q[0] is not None and q[1]:
            sims.append(min(q[0][-1], SC.CAP))
    if not sims:
        return None
    return {"y": p[0][-1] - sum(sims) / len(sims), "abs": p[0][-1], "end": p[2]}


# ===================================================================== WRDS adapter (hand-written)
# Everything above this line is copied unchanged from triage/rules.py, episodes.py, score.py, stats.py and
# qs/btstats.py by tools/wrdsq/build_tri.py. Below: the WRDS data (CRSP CIZ, Compustat, CCM, LSEG 13F, Fama-French)
# turned into the same panel records, returns and 13F rows the live triage uses, then the live detect / evaluate /
# statistics run unchanged.
#
# WRDS policy: data stays on WRDS. The report prints statistics only (counts, medians, means, regressions).
#
# Differences from the live triage (data, not rules):
#   prices      CRSP daily (dsf_v2, CIZ). Entry = CLOSE of the first trading day after the scan (live: its open).
#               Returns compound CRSP daily returns (dividends and delisting returns included); a stock that
#               delists is held as cash after its delisting return.
#   12-month    close vs the highest of the previous 24 scan closes and the change over 24 scans, from CRSP price
#               returns (split-proof).
#   fundamentals Compustat quarterly (TTM, latest balance sheet; known from the earnings date rdq, else quarter end
#               + 90 days) and annual (known from fiscal year end + 120 days). Compustat restates some figures.
#   US filter   CRSP common stock (EQTY/COM/NS) on NYSE, NYSE American or Nasdaq; US-incorporated or US-located
#               (Compustat loc); USD reporting. Industry = CRSP SIC that day (Compustat SIC when missing).
#   13F         LSEG s34: each manager's first vintage per quarter; filing date taken as the 45-day deadline.
#   insiders    no WRDS access (tr_insiders) -> the Insider Buy/Sell cell is N/A (neutral) for every event.
#   volume      average daily dollar volume over the last 6 scan periods (~3 months).
import time as _time

import numpy as _np
import pandas as _pd



def write(kind, items):                    # score.write: nothing to write on WRDS
    return None


PRICE_START, EVENT_START, END = "2006-01-01", "2008-01-01", "2025-12-31"
F13_START = "2007-06-30"
AAPL = 14593
MC_UNIT = 1000.0                           # CRSP shrout is in thousands
EXCH = ("N", "A", "Q")


def _in(sic, ranges):
    return sic is not None and any(a <= sic <= b for a, b in ranges)


def universes(sic, ticker):
    """Same industry rules as qs/screens.u_broad / u_core / u_emerging (ranges copied by build_tri.py)."""
    if sic is None or _in(sic, NEVER_SIC):
        return []
    anyway = ticker in SCREEN_ANYWAY
    u = []
    if not (_in(sic, STRUCT_EXCL) and not _in(sic, STRUCT_KEEP) and not anyway):
        u.append("broad")
    if anyway or not _in(sic, CORE_EXCL):
        u.append("core")
        if not _in(sic, EMERGING_EXTRA):
            u.append("emerging")
    return u


def holder_excluded(name, val, npos):
    if is_match(name, HOLDERS_PASSIVE) or is_match(name, HOLDERS_EXCLUDE):
        return True
    return npos > HOLDERS_MAX_POS or (val > HOLDERS_HUGE_AUM and npos > HOLDERS_HUGE_POS)


def is_match(name, patterns):
    import re
    n = " " + re.sub(r"[^A-Z0-9]+", " ", (name or "").upper()) + " "
    return any(" " + re.sub(r"[^A-Z0-9]+", " ", p.upper()).strip() + " " in n for p in patterns if p.strip())


# --------------------------------------------------------------------------------------------- calendar
def scan_days(days):
    """[(d, e)]: last trading day on or before the 15th and on or before month-end; e = next trading day."""
    days = sorted(_pd.to_datetime(days))
    s = _pd.Series(days)
    out = []
    for p in _pd.period_range(days[0], days[-1], freq="M"):
        for nominal in (_pd.Timestamp(p.year, p.month, 15), p.end_time.normalize()):
            i = s.searchsorted(nominal, side="right") - 1
            if i < 0 or i + 1 >= len(s):
                continue
            d, e = s.iat[i], s.iat[i + 1]
            if out and d <= out[-1][0]:
                continue
            out.append((d, e))
    return out


def _arr(ds):
    return "ARRAY[" + ",".join("'%s'" % x.strftime("%Y-%m-%d") for x in ds) + "]::date[]"


# --------------------------------------------------------------------------------------------- pull (SQL)
YEARS = list(range(int(PRICE_START[:4]), int(END[:4]) + 1))
F13_YEARS = list(range(int(F13_START[:4]), 2027))


def pull(sql, save, out, data=None, part="all", budget=9000):
    """Resumable pulls: each table (CRSP and 13F one per year) is saved as soon as it is read and skipped when it is
    already in ~/wrdsq/data, so a job stopped by the 3-hour limit continues where it left off when it is run again.
    part: 'crsp' | 'comp' | 'f13' | 'all'. Stops starting new tables after `budget` seconds."""
    import os
    t0 = _time.time()
    state = {"left": 0}

    def have(name):
        return bool(data) and os.path.exists(os.path.join(data, name + ".csv.gz"))

    def step(name, fn):
        if have(name):
            return None
        if _time.time() - t0 > budget:
            state["left"] += 1
            return None
        t1 = _time.time()
        df = fn()
        save(name, df)
        out("  %-14s %9d rows  %5.0f s" % (name, len(df), _time.time() - t1))
        return df

    if part in ("crsp", "all"):
        def calendar():
            cal = sql("select distinct dlycaldt as d from crsp.dsf_v2 where permno = %d and dlycaldt between '%s' "
                      "and '%s'" % (AAPL, PRICE_START, END))
            days = sorted(_pd.to_datetime(cal.d))
            assert len(days) > 4000, "trading calendar too short: %d days" % len(days)
            sc_ = scan_days(days)
            return _pd.DataFrame({"d": [d for d, _ in sc_], "e": [e for _, e in sc_]})
        step("tri_cal", calendar)
        step("tri_etf", lambda: sql(
            "select distinct permno, ticker from crsp.stksecurityinfohist where ticker in ('SPY','IWM') "
            "and securitytype = 'FUND' and secinfoenddt >= '%s'" % PRICE_START))
        assert data, "pull needs the data folder (DATA in a wrdsq python step)"
        if not (have("tri_cal") and have("tri_etf")):
            out("pull %s: calendar not read yet; run again" % part)
            return
        cal = _pd.read_csv(os.path.join(data, "tri_cal.csv.gz"), parse_dates=["d", "e"])
        etf = _pd.read_csv(os.path.join(data, "tri_etf.csv.gz"))
        sc = list(zip(cal.d, cal.e))
        etf_ids = ",".join(str(int(p)) for p in etf.permno)
        thr_e = _arr([e + _pd.Timedelta(days=1) for _, e in sc])
        thr_s = _arr([d + _pd.Timedelta(days=1) for d, _ in sc])
        for y in YEARS:
            ds = [d for d, _ in sc if d.year == y]
            if ds:
                step("tri_px_%d" % y, lambda ds=ds, y=y: sql(
                    "select permno, dlycaldt as d, abs(dlyprc)::float8 as prc, shrout::float8 as shrout, siccd, "
                    "usincflg, ticker from crsp.dsf_v2 where dlycaldt between '%d-01-01' and '%d-12-31' and "
                    "dlycaldt = any(%s) and securitytype = 'EQTY' and securitysubtype = 'COM' and sharetype = 'NS' "
                    "and primaryexch in ('N','A','Q') and dlyprc is not null and dlyprc <> 0" % (y, y, _arr(ds))))
            # period pieces: be = entry bucket (close of entry day k-1 .. close of entry day k), bs = scan bucket
            step("tri_bk_%d" % y, lambda y=y: sql(
                "select permno, width_bucket(dlycaldt, %s) as be, width_bucket(dlycaldt, %s) as bs, "
                "sum(case when dlyret is null then 0 else ln(greatest(1 + dlyret, 0.0001)) end)::float8 as lr, "
                "sum(case when coalesce(dlyretx, dlyret) is null then 0 else ln(greatest(1 + coalesce(dlyretx, dlyret), 0.0001)) end)::float8 as lrx, "
                "sum(abs(dlyprc) * coalesce(dlyvol, 0))::float8 as dv, count(*) as nd, "
                "max(case when dlydelflg = 'Y' then 1 else 0 end) as del "
                "from crsp.dsf_v2 where dlycaldt between '%d-01-01' and '%d-12-31' and "
                "((securitytype = 'EQTY' and securitysubtype = 'COM' and sharetype = 'NS') or permno in (%s)) "
                "group by 1, 2, 3" % (thr_e, thr_s, y, y, etf_ids)))
    if part in ("comp", "all"):
        step("tri_link", lambda: sql(
            "select gvkey, lpermno as permno, linkprim, linkdt, linkenddt from crsp.ccmxpf_lnkhist "
            "where linktype in ('LC','LU') and linkprim in ('P','C') and lpermno is not null"))
        step("tri_co", lambda: sql("select gvkey, sic, loc, fic from comp.company"))
        step("tri_fq", lambda: sql(
            "select gvkey, datadate, fyearq, fqtr, rdq, saleq, cogsq, xsgaq, oiadpq, oibdpq, dpq, niq, oancfy, "
            "capxy, cheq, ivltq, dlttq, dlcq, curcdq from comp.fundq where indfmt = 'INDL' and datafmt = 'STD' "
            "and popsrc = 'D' and consol = 'C' and datadate >= '2003-01-01'"))
        step("tri_fa", lambda: sql(
            "select gvkey, datadate, fyear, sale, cogs, xsga, oiadp, oibdp, dp, ni, oancf, capx, stkco, che, ivao, "
            "at, lct, dlc, dltt, ceq, txt, pi, csho, ajex, curcd from comp.funda where indfmt = 'INDL' and "
            "datafmt = 'STD' and popsrc = 'D' and consol = 'C' and datadate >= '1994-01-01'"))
        step("tri_ff", lambda: sql(
            "select date, mktrf, smb, hml, rmw, cma, rf, umd from ff.fivefactors_monthly where date >= '%s'"
            % PRICE_START))
        step("tri_cusip", lambda: sql(
            "select distinct permno, cusip, namedt, nameenddt from crsp.stocknames_v2 where cusip is not null"))
    if part in ("f13", "all"):
        for y in F13_YEARS:
            lo, hi = ("%d-01-01" % y, "%d-12-31" % y) if y > int(F13_START[:4]) else (F13_START, "%d-12-31" % y)
            step("tri_13t_%d" % y, lambda lo=lo, hi=hi: sql(
                "select mgrno, rdate, fdate, sum(shares * prc)::float8 as val, count(distinct cusip) as npos "
                "from tfn.s34 where rdate between '%s' and '%s' and shares > 0 and prc > 0 group by 1, 2, 3"
                % (lo, hi)))
            step("tri_13p_%d" % y, lambda lo=lo, hi=hi: sql(
                "with t as (select mgrno, rdate, fdate, sum(shares * prc) as val, count(distinct cusip) as npos "
                "from tfn.s34 where rdate between '%s' and '%s' and shares > 0 and prc > 0 group by 1, 2, 3) "
                "select s.mgrno, s.rdate, s.fdate, s.cusip, max(s.mgrname) as mgrname, "
                "(sum(s.shares * s.prc) / max(t.val))::float8 as w "
                "from tfn.s34 s join t on s.mgrno = t.mgrno and s.rdate = t.rdate and s.fdate = t.fdate "
                "where s.rdate between '%s' and '%s' and s.shares > 0 and s.prc > 0 and t.val >= %g and t.npos <= %d "
                "group by 1, 2, 3, 4 having sum(s.shares * s.prc) >= %g * max(t.val)"
                % (lo, hi, lo, hi, R.FUND_MIN_AUM, R.FUND_MAX_POSITIONS, R.FUND_MIN_WEIGHT)))
    if part in ("ibes", "all"):
        step("tri_ibes", lambda: sql(
            "select cusip, statpers, numest, numup, numdown from ibes.statsum_epsus where fpi = '1' and "
            "measure = 'EPS' and statpers >= '%s' and numest > 0" % PRICE_START))
    out("pull %s: %s after %.0f s" % (part, ("%d tables left for the next run" % state["left"]) if state["left"]
                                       else "complete", _time.time() - t0))


def load_years(load, base, years, **kw):
    parts = []
    for y in years:
        try:
            parts.append(load("%s_%d" % (base, y), **kw))
        except FileNotFoundError:
            continue
    return _pd.concat(parts, ignore_index=True)


def load_bk(load):
    bk = load_years(load, "tri_bk", YEARS)
    return bk.groupby(["permno", "be", "bs"], as_index=False).agg(
        lr=("lr", "sum"), lrx=("lrx", "sum"), dv=("dv", "sum"), nd=("nd", "sum"), dl=("del", "max"))


# --------------------------------------------------------------------------------------------- fundamentals
def _cagr(first, last, years):
    if first is None or last is None or years <= 0 or first <= 0 or last <= 0:
        return None
    return (last / first) ** (1.0 / years) - 1


def _num(v):
    return None if v is None or v != v else float(v)


def quarterly(fq):
    """One row per company-quarter with what the panel needs as of that quarter's earnings date."""
    q = fq.sort_values(["gvkey", "datadate"]).drop_duplicates(["gvkey", "datadate"], keep="last").copy()
    q["avail"] = q.rdq.where(q.rdq.notna() & (q.rdq >= q.datadate), q.datadate + _pd.Timedelta(days=90))
    g = q.groupby(["gvkey", "fyearq"])
    for c in ("oancfy", "capxy"):
        prev = g[c].shift(1)
        q[c[:-1] + "q"] = _np.where(q.fqtr == 1, q[c], q[c] - prev)
    q["ebitdaq"] = q.oibdpq.where(q.oibdpq.notna(), q.oiadpq + q.dpq)
    q["fcfq"] = q.oancfq - q.capxq
    gk = q.groupby("gvkey")
    span = (q.datadate - gk.datadate.shift(3)).dt.days
    ok4 = span.between(250, 300)
    for c, nm in (("oiadpq", "ebit"), ("ebitdaq", "ebitda"), ("fcfq", "fcf"), ("saleq", "rev"), ("niq", "ni"),
                  ("cogsq", "cogs4")):
        s = gk[c].rolling(4, min_periods=4).sum().reset_index(level=0, drop=True)
        q[nm] = s.where(ok4)
    q["gprep"] = q.cogsq.notna()
    q["gm"] = _np.where((q.rev > 0) & q.cogs4.notna(), (q.rev - q.cogs4) / q.rev, _np.nan)
    q["ytd"] = q.groupby(["gvkey", "fyearq"]).saleq.cumsum()
    prev = q[["gvkey", "fyearq", "fqtr", "ytd"]].dropna(subset=["fyearq", "fqtr"]).drop_duplicates(["gvkey", "fyearq", "fqtr"]).copy()
    prev["fyearq"] = prev.fyearq + 1
    q = q.merge(prev.rename(columns={"ytd": "ytd0"}), on=["gvkey", "fyearq", "fqtr"], how="left")
    q["ytdg"] = _np.where((q.fqtr < 4) & (q.ytd0 > 0), q.ytd / q.ytd0 - 1, _np.nan)
    has = q[["dlttq", "dlcq", "cheq"]].notna().any(axis=1)
    q["nd"] = (q.dlttq.fillna(0) + q.dlcq.fillna(0) - q.cheq.fillna(0) - q.ivltq.fillna(0)).where(has)
    q["debtok"] = q[["dlttq", "dlcq"]].notna().any(axis=1)
    for c in ("ebit", "ebitda", "fcf", "rev", "ni", "nd"):          # Compustat reports $ millions
        q[c] = q[c] * 1e6
    keep = ["gvkey", "avail", "ebit", "ebitda", "fcf", "rev", "ni", "gm", "gprep", "ytdg", "nd", "debtok", "curcdq"]
    return q[keep].sort_values("avail").reset_index(drop=True)


def _median_nm(vals, n_nm):
    n = len(vals) + n_nm
    if not n or n_nm * 2 >= n:
        return None
    xs = sorted(vals) + [float("inf")] * n_nm
    k = n // 2
    return xs[k] if n % 2 else (xs[k - 1] + xs[k]) / 2


def annual(fa, keep_gvkeys):
    """One row per company-fiscal year: the 10-year metrics as of that annual report (fiscal year end + 120 days)."""
    a = fa[fa.gvkey.isin(keep_gvkeys)].sort_values(["gvkey", "fyear", "datadate"])
    a = a[a.fyear.notna()].drop_duplicates(["gvkey", "fyear"], keep="last")
    rows = []
    cols = ["fyear", "datadate", "sale", "xsga", "oiadp", "oibdp", "dp", "ni", "oancf", "capx", "stkco", "che",
            "ivao", "at", "lct", "dlc", "dltt", "ceq", "txt", "pi", "csho", "ajex", "curcd"]
    for gv, g in a.groupby("gvkey", sort=False):
        recs = g[cols].to_dict("records")
        yr = {}
        ic = {}
        for r in recs:
            r = {k: (_num(v) if k not in ("datadate", "curcd") else v) for k, v in r.items()}
            y = int(r["fyear"])
            rev, op, da = r["sale"], r["oiadp"], r["dp"]
            ebitda = r["oibdp"] if r["oibdp"] is not None else ((op + da) if (op is not None and da is not None) else None)
            ocf, cap = r["oancf"], r["capx"]
            fcf = (ocf - cap) if (ocf is not None and cap is not None) else None
            t = 0.25
            if r["pi"] and r["pi"] > 0 and r["txt"] is not None and r["txt"] >= 0:
                t = min(max(r["txt"] / r["pi"], 0.0), 0.40)
            nopat = op * (1 - t) if op is not None else None
            che, ivao, dlc = r["che"] or 0, r["ivao"] or 0, r["dlc"] or 0
            if r["at"] is not None and r["lct"] is not None:
                ic[y] = r["at"] - che - ivao - (r["lct"] - dlc)
            elif r["ceq"] is not None and r["ceq"] != 0:
                ic[y] = r["ceq"] + (r["dltt"] or 0) + dlc - che
            icav = [x for x in (ic.get(y), ic.get(y - 1)) if x is not None] if ic.get(y) is not None else []
            ic_avg = sum(icav) / len(icav) if icav else None
            roic, neg = None, False
            if nopat is not None and ic_avg is not None:
                light = not (ic_avg > 0.02 * (rev or 0) and ic_avg > 0)
                if not light:
                    roic = max(nopat / ic_avg, -5.0)
                elif nopat > 0:
                    neg = True
            sh = (r["csho"] * r["ajex"]) if (r["csho"] and r["ajex"]) else None
            ratio = (lambda a_, b_: a_ / b_ if (a_ is not None and b_) else None)
            yr[y] = {"rev": rev, "op": op, "da": da, "ebitda": ebitda, "ni": r["ni"], "fcf": fcf, "sbc": r["stkco"],
                     "roic": roic, "neg": neg, "sh": sh, "om": ratio(op, rev), "em": ratio(ebitda, rev),
                     "sga": ratio(r["xsga"], rev)}
            if rev is None or op is None:
                continue
            full = [z for z in sorted(yr) if yr[z]["rev"] is not None and yr[z]["op"] is not None]
            L = y
            W = [z for z in full if L - 10 < z <= L]
            lr = yr[L]
            m = {"gvkey": gv, "fy": L, "fyend": r["datadate"], "acur": r["curcd"], "yrs": len(W), "ytot": len(full),
                 "revfy": rev, "fyebit": op, "fyebitda": ebitda,
                 "das": (abs(da) / ebitda) if (da is not None and ebitda and ebitda > 0) else None,
                 "lossy": sum(1 for z in W if yr[z]["op"] <= 0)}
            roics = [yr[z]["roic"] for z in W if yr[z]["roic"] is not None]
            n_nm = sum(1 for z in W if yr[z]["neg"])
            m["roic"] = _median_nm(roics, n_nm)
            m["roics"] = ((sum(1 for x in roics if x >= 0.10) + n_nm) / (len(roics) + n_nm)) if (roics or n_nm) else None
            span = W[-1] - W[0]
            m["rc"] = _cagr(yr[W[0]]["rev"], rev, span) if span >= 5 else None
            m["rc3"] = _cagr(yr[L - 3]["rev"], rev, 3) if (L - 3) in yr else None
            p1 = yr.get(L - 1)
            m["fyg"] = (rev / p1["rev"] - 1) if (p1 and p1["rev"] and p1["rev"] > 0) else None
            p3 = yr.get(L - 3)
            for k_, src in (("em3", "em"), ("om3", "om"), ("sga3", "sga")):
                m[k_] = (lr[src] - p3[src]) if (p3 and lr[src] is not None and p3[src] is not None) else None
            rts = []
            for z in range(L - 2, L + 1):
                a_, b_ = yr.get(z, {}).get("sh"), yr.get(z - 1, {}).get("sh")
                if a_ and b_:
                    rts.append(a_ / b_)
            m["sh3"] = (float(_np.prod(rts)) ** (1.0 / len(rts)) - 1) if len(rts) >= 3 else None
            pairs = [(yr[z]["fcf"] - abs(yr[z]["sbc"] or 0), yr[z]["ni"]) for z in W
                     if yr[z]["fcf"] is not None and yr[z]["ni"] is not None]
            sni = sum(p[1] for p in pairs)
            m["fcfc"] = (sum(p[0] for p in pairs) / sni) if (len(pairs) >= 5 and sni > 0) else None
            rows.append(m)
    A = _pd.DataFrame(rows)
    for c in ("revfy", "fyebit", "fyebitda"):                       # Compustat reports $ millions
        A[c] = A[c] * 1e6
    A["avail"] = _pd.to_datetime(A.fyend) + _pd.Timedelta(days=120)
    return A.sort_values("avail").reset_index(drop=True)


# --------------------------------------------------------------------------------------------- panel
class Panel:
    def __init__(self, load, out):
        cal = load("tri_cal", parse_dates=["d", "e"])
        self.d = list(cal.d)
        self.e = list(cal.e)
        self.ids = [x.strftime("%Y-%m-%d") for x in self.d]
        n = len(self.d)
        px = load_years(load, "tri_px", YEARS, parse_dates=["d"])
        px = px[px.d.isin(set(self.d))]
        k_of = {d: i for i, d in enumerate(self.d)}
        px["k"] = px.d.map(k_of)
        px["mc"] = px.prc * px.shrout * MC_UNIT
        perms = _np.sort(px.permno.unique())
        self.col = {p: j for j, p in enumerate(perms)}
        bk = load_bk(load)
        self.etf = load("tri_etf")
        # scan buckets: bs = i covers (d[i-1], d[i]] -> price change into scan i; dollar volume over that period
        b = bk[bk.permno.isin(self.col) & (bk.bs >= 1) & (bk.bs <= n - 1)]
        sb = b.groupby(["permno", "bs"], as_index=False).agg(lrx=("lrx", "sum"), dv=("dv", "sum"), nd=("nd", "sum"))
        ci = sb.permno.map(self.col).to_numpy()
        LRX = _np.zeros((n, len(perms)))
        DV = _np.zeros((n, len(perms)))
        ND = _np.zeros((n, len(perms)))
        LRX[sb.bs.to_numpy(), ci] = sb.lrx.to_numpy()
        DV[sb.bs.to_numpy(), ci] = sb.dv.to_numpy()
        ND[sb.bs.to_numpy(), ci] = sb.nd.to_numpy()
        self.L = _np.cumsum(LRX, axis=0)                        # log price index at each scan close
        self.PRES = _np.zeros((n, len(perms)), bool)
        self.PRES[px.k.to_numpy(), px.permno.map(self.col).to_numpy()] = True
        self.DVc, self.NDc = _np.cumsum(DV, axis=0), _np.cumsum(ND, axis=0)
        self.px = {k: g for k, g in px.groupby("k")}
        # links and fundamentals
        link = load("tri_link", parse_dates=["linkdt", "linkenddt"])
        link["linkenddt"] = link.linkenddt.fillna(_pd.Timestamp("2099-12-31"))
        link["gvkey"] = link.gvkey.astype(str).str.zfill(6)
        link["permno"] = link.permno.astype(int)
        link = link[link.permno.isin(self.col)]
        link["pri"] = (link.linkprim == "P").astype(int)
        self.link = link
        co = load("tri_co", dtype={"gvkey": str, "sic": str, "loc": str})
        co["gvkey"] = co.gvkey.str.zfill(6)
        self.co = co.set_index("gvkey")
        fq = load("tri_fq", parse_dates=["datadate", "rdq"], dtype={"gvkey": str})
        fq["gvkey"] = fq.gvkey.str.zfill(6)
        fq = fq[fq.gvkey.isin(set(link.gvkey))]
        self.Q = quarterly(fq)
        fa = load("tri_fa", parse_dates=["datadate"], dtype={"gvkey": str})
        fa["gvkey"] = fa.gvkey.str.zfill(6)
        t0 = _time.time()
        self.A = annual(fa, set(link.gvkey))
        out("panel inputs: %d scans, %d stocks, %d company-quarters, %d company-years (%.0f s)"
            % (n, len(perms), len(self.Q), len(self.A), _time.time() - t0))
        self.sizes, self.mcs = [], []

    def load(self, ym):
        k = self.ids.index(ym) if ym in self.ids else None
        if k is None or k not in self.px:
            return None
        d = self.d[k]
        g = self.px[k].copy()
        lk = g[["permno"]].merge(self.link, on="permno")
        lk = lk[(lk.linkdt <= d) & (lk.linkenddt >= d)].sort_values(["permno", "pri"], ascending=[True, False])
        lk = lk.drop_duplicates("permno")
        g = g.merge(lk[["permno", "gvkey"]], on="permno")
        g = g.join(self.co[["sic", "loc"]], on="gvkey")
        g["avail"] = d
        g = g.sort_values("avail")
        g = _pd.merge_asof(g, self.Q, on="avail", by="gvkey", direction="backward")
        g = _pd.merge_asof(g, self.A.drop(columns=["fy"]), on="avail", by="gvkey", direction="backward")
        us = (g.usincflg == "Y") | (g["loc"] == "USA")
        g = g[us & (g.curcdq == "USD") & (g.acur == "USD")]
        cols = g.permno.map(self.col).to_numpy()
        lo = max(0, k - R.PER_YEAR)
        win = _np.where(self.PRES[lo:k][:, cols], self.L[lo:k][:, cols], -_np.inf) if k > lo else None
        Lk = self.L[k, cols]
        if win is not None:
            mx = win.max(axis=0)
            g["dd"] = _np.where(_np.isfinite(mx), _np.exp(Lk - mx) - 1, _np.nan)
        else:
            g["dd"] = _np.nan
        if k >= R.PER_YEAR:
            j = k - R.PER_YEAR
            g["r12"] = _np.where(self.PRES[j, cols], _np.exp(Lk - self.L[j, cols]) - 1, _np.nan)
        else:
            g["r12"] = _np.nan
        j0 = max(0, k - 6)
        dv = self.DVc[k, cols] - self.DVc[j0, cols]
        nd = self.NDc[k, cols] - self.NDc[j0, cols]
        g["adv"] = _np.where(nd > 0, dv / _np.maximum(nd, 1), _np.nan)
        g["ev"] = g.mc + g.nd
        g["ylf"] = (d - _pd.to_datetime(g.fyend)).dt.days / 365.25
        sic = g.siccd.where(g.siccd.fillna(0) > 0, _pd.to_numeric(g.sic, errors="coerce"))
        g["sicn"] = sic
        recs = {}
        fields = ["px", "mc", "ev", "adv", "dd", "r12", "ebit", "ebitda", "fcf", "rev", "ni", "fyebit", "fyebitda",
                  "das", "nd", "yrs", "ytot", "ylf", "rc3", "rc", "ytdg", "fyg", "roic", "roics", "gm", "em3", "om3",
                  "sga3", "sh3", "fcfc", "lossy", "revfy"]
        g = g.rename(columns={"prc": "px"})
        for r in g[fields + ["permno", "ticker", "sicn", "gprep", "debtok"]].to_dict("records"):
            rec = {f: (None if (r[f] is None or r[f] != r[f]) else float(r[f])) for f in fields}
            for f in ("yrs", "ytot", "lossy"):
                if rec[f] is not None:
                    rec[f] = int(rec[f])
            s = r["sicn"]
            s = None if s is None or s != s else int(s)
            tk = r["ticker"] if isinstance(r["ticker"], str) else ""
            rec.update({"tk": tk, "nm": "", "sym": None, "sic": ("%04d" % s) if s is not None else "",
                        "gprep": bool(r["gprep"]) if r["gprep"] == r["gprep"] else False,
                        "debtok": bool(r["debtok"]) if r["debtok"] == r["debtok"] else False,
                        "u": universes(s, tk)})
            recs[str(int(r["permno"]))] = rec
        self.sizes.append(len(recs))
        self.mcs.append(float(g.mc.median()) if len(g) else _np.nan)
        return {"ym": ym, "d": ym, "e": self.e[k].strftime("%Y-%m-%d"), "companies": recs}

    def returns(self, bk):
        """r[scan id] = {permno: [return from this scan's entry close to the next one's, 'ok' | 'exit']} for stocks
        that traded on the entry day; idx[scan id] = {'SPY': r, 'IWM': r}."""
        n = len(self.d)
        on_e = bk[(bk.bs == bk.be + 1)]                     # the piece holding entry day k alone: (d_k, e_k]
        on_e = on_e[on_e.nd > 0][["permno", "be", "dl"]].rename(columns={"dl": "dl_e"})
        per = bk[(bk.be >= 1) & (bk.be <= n - 1)].groupby(["permno", "be"], as_index=False).agg(
            lr=("lr", "sum"), dl=("dl", "max"))
        per["k"] = per.be - 1                               # entry bucket k+1 = (e_k, e_{k+1}] -> period of scan k
        on_e = on_e.assign(k=on_e.be)
        m = on_e[on_e.dl_e == 0][["permno", "k"]].merge(per[["permno", "k", "lr", "dl"]], on=["permno", "k"],
                                                         how="left")
        r = {}
        for k, g in m.groupby("k"):
            if k > n - 2:
                continue
            vals = g.lr.fillna(0).to_numpy()
            r[self.ids[k]] = {str(int(p)): [float(_np.exp(v) - 1), "exit" if dl == 1 else "ok"]
                              for p, v, dl in zip(g.permno, vals, g.dl.fillna(0))}
        for k in range(n - 1):
            r.setdefault(self.ids[k], {})
        idx = {self.ids[k]: {} for k in range(n - 1)}
        for p, t in zip(self.etf.permno, self.etf.ticker):
            e = per[per.permno == p]
            for k, v in zip(e.k, e.lr):
                if 0 <= k <= n - 2:
                    idx[self.ids[k]][t] = float(_np.exp(v) - 1)
        return r, idx


class WReturns(Returns):
    def __init__(self, months, grid_e, r, idx):
        self.months, self.e, self.r, self.idx = months, grid_e, r, idx
        self.mark, self.opens, self.splits, self.divs = {}, {}, {}, {}


def owners_rows(load, out):
    tot = load_years(load, "tri_13t", F13_YEARS, parse_dates=["rdate", "fdate"])
    first = tot.sort_values("fdate").drop_duplicates(["mgrno", "rdate"])
    pos = load_years(load, "tri_13p", F13_YEARS, parse_dates=["rdate", "fdate"])
    pos = pos.merge(first[["mgrno", "rdate", "fdate", "val", "npos"]], on=["mgrno", "rdate", "fdate"])
    cus = load("tri_cusip", parse_dates=["namedt", "nameenddt"])
    cus["nameenddt"] = cus.nameenddt.fillna(_pd.Timestamp("2099-12-31"))
    pos = pos.merge(cus, on="cusip")
    pos = pos[(pos.rdate >= pos.namedt - _pd.Timedelta(days=92)) & (pos.rdate <= pos.nameenddt + _pd.Timedelta(days=92))]
    pos = pos.sort_values("w", ascending=False).drop_duplicates(["mgrno", "rdate", "permno"])
    excl = {}
    rows = []
    for mg, nm, rd, w, p, val, npos in zip(pos.mgrno, pos.mgrname, pos.rdate, pos.w, pos.permno, pos.val, pos.npos):
        key = (mg, nm, val > HOLDERS_HUGE_AUM, npos)
        if key not in excl:
            excl[key] = holder_excluded(nm if isinstance(nm, str) else "", val, npos)
        if excl[key]:
            continue
        per = rd.strftime("%Y-%m-%d")
        fd = (rd + _pd.Timedelta(days=45)).strftime("%Y-%m-%d")
        rows.append([str(int(mg)), nm if isinstance(nm, str) else str(int(mg)), per, fd, str(int(p)), round(float(w), 4)])
    first_day = pos.rdate.min().strftime("%Y-%m-%d") if len(pos) else None
    through = (pos.rdate.max() + _pd.Timedelta(days=45)).strftime("%Y-%m-%d") if len(pos) else None
    out("13F: %d conviction positions (3%%+, $100M+ filers, passive / fund-house / quant names left out: %d manager "
        "names), %s .. %s" % (len(rows), sum(excl.values()), first_day, through))
    return rows, through, first_day


def factors_of(load):
    ff = load("tri_ff", parse_dates=["date"])
    out = {}
    for r in ff.itertuples():
        if any(_pd.isna(getattr(r, c)) for c in ("mktrf", "smb", "hml", "rmw", "cma", "rf", "umd")):
            continue
        out[r.date.strftime("%Y-%m")] = {"Mkt-RF": float(r.mktrf), "SMB": float(r.smb), "HML": float(r.hml),
                                         "RMW": float(r.rmw), "CMA": float(r.cma), "UMD": float(r.umd),
                                         "RF": float(r.rf)}
    return out


# --------------------------------------------------------------------------------------------- run
def three_year(rets, ev, ci):
    """(own %, similar stocks' average %, complete?) over 36 months (72 scan periods) from the call's entry."""
    n = 3 * R.PER_YEAR
    own = rets.path(ev["cik"], None, ci, n=n)
    if own[0] is None:
        return None, None, False
    sims = []
    for c in ev.get("sim") or []:
        p_ = rets.path(c, None, ci, n=n)
        if p_[0] is not None and len(p_[0]) == len(own[0]):
            sims.append(min(p_[0][-1], 3 * CAP))
    ctrl = round(100 * sum(sims) / len(sims), 1) if sims else None
    return round(100 * own[0][-1], 1), ctrl, bool(own[1])


def run(load, save, out):
    t0 = _time.time()
    pnl = Panel(load, out)
    months = list(pnl.ids)
    e_of = {pnl.ids[k]: pnl.e[k].strftime("%Y-%m-%d") for k in range(len(months))}
    quiet = []
    events = detect(months, load=pnl.load, log=quiet.append)
    out("panel: median %d US companies per scan (min %d, max %d), median market cap $%.0fM; detection %.0f s"
        % (int(_np.median(pnl.sizes)), min(pnl.sizes), max(pnl.sizes), _np.nanmedian(pnl.mcs) / 1e6,
           _time.time() - t0))
    r, idx = pnl.returns(load_bk(load))
    rets = WReturns(months, e_of, r, idx)
    rows, through, first_day = owners_rows(load, out)
    owners = Owners(rows, through, first_day)
    names = owners.names
    allev = []
    for kind in KIND_IDS:
        events[kind] = [ev for ev in events[kind] if ev["d"] >= EVENT_START]
        for ev in events[kind]:
            ev["kind"] = kind
            ev["fund"] = owners.funds(str(ev["cik"]), ev["d"])
            ev["ins"] = {"n": 0, "net": None}                  # no insider data on WRDS: cell set to N/A below
            ev["learn"] = _event_learning(ev, rets)
            if ev["learn"] and ev["fund"]:
                allev.append({"y": ev["learn"]["y"], "end": ev["learn"]["end"], "fund": ev["fund"], "cik": ev["cik"]})
    as_of = top_performers(allev)
    factors = factors_of(load)
    months_d = list(months)
    res, flat = {}, []
    for kind in KIND_IDS:
        items, series = [], {}
        for ev in events[kind]:
            f = ev.get("fund")
            if f:
                tops = as_of(ev["d"][:7] + "-01")
                ev["top"] = [(names.get(fc, fc), tops[fc][0], tops[fc][2], tops[fc][3]) for fc, *_ in f["list"] if fc in tops]
                ev["top_later"] = []
                for fc, nm, _w, fd in f["later"]:
                    t = as_of(fd[:7] + "-01").get(fc)
                    if t:
                        ev["top_later"].append((names.get(fc, nm), t[0], t[2], t[3], fd))
                ev["top_later"].sort(key=lambda t: t[4])
            item, _ = evaluate(kind, ev, through, months_d, rets, R.INDEX[kind][0])
            if item.get("no_entry"):
                continue
            item["factors"]["insider"] = list(NA)
            ci = months_d.index(item["call_date"]) if item["call_date"] in months_d else ev["i"]
            if item["upgraded"]:
                ci = next((j for j, dd in enumerate(months_d) if dd >= item["call_date"]), ev["i"])
            series[item["id"]] = rets.series(ev["cik"], None, ci, None)
            items.append(item)
            r3 = three_year(rets, ev, ci)
            flat.append({"kind": kind, "permno": ev["cik"], "scan": ev["d"], "call_date": item["call_date"],
                         "call": {"overdone": "Buy", "close": "Watch", "justified": "Avoid"}.get(item["verdict"], item["verdict"]),
                         "upgraded": bool(item["upgraded"]), "score": item["score"], "ret": item.get("ret"),
                         "ctrl_ret": item.get("ctrl_ret"), "idx_ret": item.get("idx_ret"), "played": item.get("played"),
                         "stopped": item.get("stopped"), "p_own": item.get("p_own"), "p_peer": item.get("p_peer"),
                         "id": item["id"], "ret3": r3[0], "ctrl3": r3[1], "played3": r3[2],
                         **{"c_" + k: c[0] if c[1] != "N/A" else "" for k, c in item["factors"].items()}})
        res[kind] = (items, series, summary(kind, items, series, factors))
    save("tri_events", _pd.DataFrame(flat))
    save("tri_series", _pd.DataFrame([(i, per, r_) for _k, (_it, ser, _s) in res.items() for i, sr in ser.items()
                                      for per, r_ in sr.items()], columns=["id", "per", "r"]))
    report(res, out)
    out("\nrun done in %.0f s" % (_time.time() - t0))


# --------------------------------------------------------------------------------------------- report (stats only)
LAB = {"overdone": "Buy", "close": "Watch", "justified": "Avoid", "tbu": "TBU"}


def _calls_lines(out, ct, pre="  "):
    out(pre + "%-6s %6s %8s %8s %9s %8s %6s %6s %7s" % ("call", "n", "median%", "mean%", "similar%", "index%",
                                                         "beat%", "up20%", "down50%"))
    for v in ("overdone", "close", "justified"):
        c = ct.get(v)
        if c:
            out(pre + "%-6s %6d %8s %8s %9s %8s %6s %6s %7s" % (LAB[v], c["n"], c["median"], c["mean"], c["ctrl_mean"],
                                                                 c["idx_mean"], c["beat"], c["up20"], c["down50"]))


def report(res, out):
    for kind, (items, series, summ) in res.items():
        k = R.KINDS[kind]
        out("\n" + "=" * 100 + "\n%s (%s)" % (k["label"], kind))
        byv = {v: sum(1 for x in items if x["verdict"] == v) for v in ("overdone", "close", "justified", "tbu")}
        out("events %d: %s; upgraded Watch->Buy %d; with a full year %d"
            % (len(items), ", ".join("%s %d" % (LAB[v], n) for v, n in byv.items()),
               sum(1 for x in items if x.get("upgraded")), sum(1 for x in items if x.get("played"))))
        yrs = {}
        for x in items:
            yrs.setdefault(x["date"][:4], [0, 0])
            yrs[x["date"][:4]][0] += 1
            yrs[x["date"][:4]][1] += x["verdict"] == "overdone"
        out("events by year (all / Buy): " + "  ".join("%s %d/%d" % (y, a, b) for y, (a, b) in sorted(yrs.items())))
        out("\none-year results by call (each return capped at +500%% in means; similar = 10 most similar stocks; "
            "index = %s):" % R.INDEX[kind][1])
        _calls_lines(out, summ["calls"])
        for lab, lo, hi in (("2008-2012", "2008", "2012-12-31"), ("2013-2018", "2013", "2018-12-31"),
                            ("2019-2024", "2019", "2024-12-31")):
            sub = [x for x in items if lo <= x["call_date"] <= hi]
            out("  -- %s" % lab)
            _calls_lines(out, calls_table(sub), "     ")
        y = summ.get("years") or {}
        out("\n$10,000 split over each year's Buy candidates (own / similar / index; n):")
        out("  " + "  ".join("%s %s/%s/%s (%d)" % (yy, v["own"], v["ctrl"], v["idx"], v["n"]) for yy, v in sorted(y.items())))
        reg = summ.get("regression") or {}
        out("\ncalendar-time portfolios, Fama-French 5 + momentum, Newey-West t (alpha per year, %):")
        for v in ("overdone", "close", "justified", "long_short"):
            g = reg.get(v)
            if not g or g.get("alpha_y") is None:
                continue
            b = g.get("betas") or {}
            out("  %-10s n=%3d alpha %+6.1f%%/yr (t %5.2f) R2 %s | %s" % (
                LAB.get(v, "Buy-Avoid"), g["n"], g["alpha_y"], g["t"], g.get("r2"),
                " ".join("%s %+.2f(%.1f)" % (kk, bb[0], bb[1]) for kk, bb in b.items())))
        out("\nper cell: one-year return minus similar stocks (median / mean %, beat %, n) green | neutral | red:")
        for key, e in (summ.get("evidence") or {}).items():
            cells = []
            for col in ("g", "n", "r"):
                c = e["cols"].get(col)
                cells.append("%s %s/%s %s%% n%d" % (col, c["median"], c["mean"], c["beat"], c["n"]) if c else "%s -" % col)
            out("  %-24s w%-3d %s  (N/A %d)" % (e["label"], e["weight"], " | ".join(cells), e["na"]))


# ===================================================================== research tests (docs/research/triage_wrds/PLAN.md)
TRAIN_END, TEST_START, TEST_END = "2015-12-31", "2016-01-01", "2024-12-31"
REV_DAYS, REV_GREEN, REV_RED = 92, 0.10, -0.10
FLAG_AT, FLAG_MIN_N = -5.0, 100
PTS = {"g": 1.0, "r": -1.0}


def ibes_colours(ev, load):
    """Estimate revisions cell (research only): net upward revisions of next-year EPS estimates over the 3 months to
    the scan, (ups - downs) / estimates, from I/B/E/S summary files dated on or before the scan day."""
    ib = load("tri_ibes", parse_dates=["statpers"], dtype={"cusip": str})
    cus = load("tri_cusip", parse_dates=["namedt", "nameenddt"], dtype={"cusip": str})
    cus["nameenddt"] = cus.nameenddt.fillna(_pd.Timestamp("2099-12-31"))
    ib = ib.merge(cus, on="cusip")
    ib = ib[(ib.statpers >= ib.namedt - _pd.Timedelta(days=92)) & (ib.statpers <= ib.nameenddt + _pd.Timedelta(days=92))]
    ib = ib.drop_duplicates(["permno", "statpers"])[["permno", "statpers", "numest", "numup", "numdown"]]
    e = ev[["eid", "permno", "scan"]].merge(ib, on="permno")
    e = e[(e.statpers <= e.scan) & (e.statpers > e.scan - _pd.Timedelta(days=REV_DAYS))]
    g = e.groupby("eid").agg(up=("numup", "sum"), dn=("numdown", "sum"), n=("numest", "sum"))
    br = (g.up.fillna(0) - g.dn.fillna(0)) / g.n
    col = _np.where(br >= REV_GREEN, "g", _np.where(br <= REV_RED, "r", "n"))
    return _pd.Series(col, index=g.index)


def _excess(d):
    return (d.ret.clip(upper=CAP_PCT) - d.ctrl_ret)


def _cluster_t(d, col):
    m = d.groupby(d.call_date.str[:7])[col].mean()
    return (m.mean() / (m.std(ddof=1) / _np.sqrt(len(m)))) if len(m) > 2 and m.std(ddof=1) > 0 else _np.nan


def _row(d, lab):
    if not len(d):
        return "  %-26s n 0" % lab
    x = _excess(d)
    return "  %-26s n %5d  excess vs similar: median %+6.1f mean %+6.1f  beat %3.0f%%  down50 %3.0f%%  (t by month %+.2f)" % (
        lab, len(d), x.median(), x.mean(), 100 * (x > 0).mean(), 100 * (d.ret <= -50).mean(),
        _cluster_t(d.assign(x=x), "x"))


def _ct(items_by_verdict, series, factors, out, labels):
    items = [{"id": i, "verdict": v} for v, ids in items_by_verdict.items() for i in ids]
    reg = regression(items, series, factors) or {}
    for v in ("overdone", "close", "justified", "long_short"):
        g = reg.get(v)
        if g and g.get("alpha_y") is not None:
            out("    %-14s n=%3d months  alpha %+5.1f%%/yr (t %5.2f)  RMW %+.2f  SMB %+.2f  UMD %+.2f" % (
                labels.get(v, "top - bottom"), g["n"], g["alpha_y"], g["t"], g["betas"]["RMW"][0],
                g["betas"]["SMB"][0], g["betas"]["UMD"][0]))


def research(load, save, out):
    ev = load("tri_events", dtype={"id": str})
    ev = ev[ev.call.isin(["Buy", "Watch", "Avoid"])].copy()
    ev["eid"] = _np.arange(len(ev))
    ev["scan"] = _pd.to_datetime(ev.scan)
    ev["c_rev"] = ev.eid.map(ibes_colours(ev, load)).fillna("")
    ser = load("tri_series")
    series = {}
    for i, per, r_ in zip(ser.id, ser.per, ser.r):
        series.setdefault(i, {})[per] = r_
    factors = factors_of(load)
    done = ev[(ev.played == True) & ev.ret.notna() & ev.ctrl_ret.notna()]  # noqa: E712
    out("events with a full year: %d; with an I/B/E/S revisions colour: %.0f%%" % (len(done), 100 * (done.c_rev != "").mean()))
    lab3 = {"overdone": "Buy", "close": "Watch", "justified": "Avoid"}
    for kind in KIND_IDS:
        k = R.KINDS[kind]
        cells = [c for c, _, _ in k["cells"] if c != "insider"] + ["rev"]
        d = done[done.kind == kind]
        tr = d[d.call_date <= TRAIN_END]
        te = d[(d.call_date >= TEST_START) & (d.call_date <= TEST_END)]
        out("\n" + "=" * 100 + "\n%s: train %d events (2008-2015), test %d (2016-2024)" % (k["label"], len(tr), len(te)))
        # 0. the pre-registered rules on the test years
        out("\n0) pre-registered calls, test years:")
        for c in ("Buy", "Watch", "Avoid"):
            out(_row(te[te.call == c], c))
        _ct({"overdone": list(te[te.call == "Buy"].id), "close": list(te[te.call == "Watch"].id),
             "justified": list(te[te.call == "Avoid"].id)}, series, factors, out, lab3)
        # 1. estimate revisions cell (new), all years
        out("\n1) I/B/E/S estimate revisions cell (net up-revisions over 3 months; green >= +10%, red <= -10%), all years:")
        for c, lab in (("g", "green (raised)"), ("n", "neutral"), ("r", "red (cut)"), ("", "no estimates")):
            out(_row(d[d.c_rev == c], lab))
        # 2. walk-forward learned weights
        X = lambda df: _np.column_stack([_np.ones(len(df))] + [df["c_" + c].map(PTS).fillna(0).to_numpy() for c in cells])  # noqa: E731
        y = _excess(tr)
        lo, hi = y.quantile(0.01), y.quantile(0.99)
        b = _np.linalg.lstsq(X(tr), y.clip(lo, hi).to_numpy(), rcond=None)[0]
        out("\n2) weights fitted on 2008-2015 (points of excess return per green/red step): " +
            ", ".join("%s %+.1f" % (c, w) for c, w in zip(cells, b[1:])))
        tes = te.assign(sc=X(te) @ b)
        q = tes.sc.rank(pct=True)
        top, mid, bot = tes[q > 2 / 3], tes[(q > 1 / 3) & (q <= 2 / 3)], tes[q <= 1 / 3]
        out("   test years, by fitted score:")
        for g_, lab in ((top, "top third"), (mid, "middle third"), (bot, "bottom third")):
            out(_row(g_, lab))
        _ct({"overdone": list(top.id), "close": list(mid.id), "justified": list(bot.id)}, series, factors, out,
            {"overdone": "top third", "close": "middle third", "justified": "bottom third"})
        # 3. avoid filter from the training years' red flags
        flags = []
        for c in cells:
            red = tr[tr["c_" + c] == "r"]
            rest = tr[tr["c_" + c] != "r"]
            if len(red) >= FLAG_MIN_N and _excess(red).median() - _excess(rest).median() <= FLAG_AT:
                flags.append(c)
        out("\n3) red flags chosen on 2008-2015 (red trails the rest by %.0f+ pts, n >= %d): %s" % (
            -FLAG_AT, FLAG_MIN_N, ", ".join(flags) or "none"))
        if flags:
            flagged = te[(te[["c_" + c for c in flags]] == "r").any(axis=1)]
            clean = te[~te.id.isin(flagged.id)]
            out(_row(clean, "test: no red flag"))
            out(_row(flagged, "test: any red flag"))
            _ct({"overdone": list(clean.id), "justified": list(flagged.id)}, series, factors, out,
                {"overdone": "no red flag", "justified": "red flag"})
        # 4. three-year horizon (events through 2022)
        d3 = ev[(ev.kind == kind) & (ev.played3 == True) & ev.ret3.notna() & ev.ctrl3.notna()]  # noqa: E712
        out("\n4) three years after the call (events 2008-2022):")
        for c in ("Buy", "Watch", "Avoid"):
            x = d3[d3.call == c]
            if len(x):
                ex = x.ret3.clip(upper=1500) - x.ctrl3
                out("  %-6s n %5d  own median %+6.1f  similar median %+6.1f  excess median %+6.1f mean %+6.1f  beat %3.0f%%"
                    % (c, len(x), x.ret3.median(), x.ctrl3.median(), ex.median(), ex.mean(), 100 * (ex > 0).mean()))
